import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import { expectRecordTitle, recordIdFromView, showRelatedList, waitForSpinners } from '../../support/lightning.js';
import { soqlValue } from '../../support/api.js';

test.describe('SF-219 Create Contact from Account related list - Contact linked to Account automatically', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-032 Create Contact from Account related list - Contact linked to Account automatically',
    { tag: ['@functional', '@P0', '@SF-219', '@persona:sales-rep', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P0',
        severity: 'critical',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-032',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const email = data.unique('email');
      const phone = data.unique('phone');
      const viewed: Record<string, string> = {};
      await data.create('account-contact', ['Account', 'Contact']);
      await test.step('1. Navigate to Account record page and open the Contacts related list', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): Account 'Acme Test' record page displays with Contacts related list visible
        await accountRecordPage.open(data.id('Account'));
        viewed['Account'] = await recordIdFromView(page, 'Account');
        await expectRecordTitle(page, data.value('Account', 'Name'));
      });
      await test.step('2. Click New in the Contacts related list', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): New Contact modal opens with Account Name field pre-populated with 'Acme Test' and read-only
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await expect(newContactDialog.root).toBeVisible();
      });
      await test.step("3. Enter First Name 'John', Last Name 'Doe', Email '<EMAIL_1>', Phone '<PHONE_1>', Title 'Manager'", async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): All fields accept the entered values without validation errors
        await newContactDialog.firstName.fill('John');
        await newContactDialog.lastName.fill('Doe');
        await newContactDialog.email.fill(email);
        await newContactDialog.phone.fill(phone);
        await newContactDialog.title.fill('Manager');
        await expect(newContactDialog.firstName).toHaveValue('John');
        await expect(newContactDialog.lastName).toHaveValue('Doe');
        await expect(newContactDialog.email).toHaveValue(email);
        await expect(newContactDialog.phone).toHaveValue(phone);
        await expect(newContactDialog.title).toHaveValue('Manager');
      });
      await test.step('4. Click Save', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1): Contact record is created and the Contact detail page opens showing Account Name = 'Acme Test'
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await data.adopt('Contact', 'Contact', 'Email', email);
        viewed['Contact'] = await recordIdFromView(page, 'Contact');
      });
      await test.step("5. Verify the created Contact's Account Name field value via SOQL query", async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC1, BRD-CON-012#BR-01): SOQL query returns the Contact with AccountId matching 'Acme Test' Account Id
        await expect
          .poll(() => soqlValue(sf, 'Contact', viewed['Contact'] ?? '', 'AccountId'))
          .toBe(viewed['Account'] ?? '');
      });
    },
  );
});
